def test_AC8_13_128_detects_direct_detached_owner_uuid4_shortcuts(tmp_path: Path) -> None: 'AC8.13.128'; test_file = tmp_path / 'apps' / 'backend' / 'tests' / 'accounting' / 'test_shortcut.py'; test_file.parent.mkdir(parents=True); test_file.write_text('\nfrom uuid import uuid4\n\nfrom src.models import Account, User\n\n\ndef test_shortcut(db):\n    User(id=uuid4(), email="ok@example.com", hashed_password="x")\n    account = Account(user_id=uuid4(), name="Detached", type="ASSET", currency="SGD")\n    db.add(account)\n'.lstrip(), encoding='utf-8'); findings = detached_owner_guard.scan_paths([tmp_path / 'apps' / 'backend' / 'tests'], repo_root=tmp_path); assert [finding.relative_path for finding in findings] == ['apps/backend/tests/accounting/test_shortcut.py']; assert findings[0].line == 8; assert findings[0].pattern == 'user_id=uuid4()'; 'AC8.13.128'; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); 'AC8.13.128'; _m1_test_file = _m1_tmp / 'shortcut.py'; _m1_test_file.write_text('\nimport uuid\n\nfrom src.models import Account\n\n\ndef test_shortcut(db):\n    db.add(Account(user_id=uuid.uuid4(), name="Detached", type="ASSET", currency="SGD"))\n'.lstrip(), encoding='utf-8'); _m1_findings = detached_owner_guard.scan_paths([_m1_test_file], repo_root=_m1_tmp); assert len(_m1_findings) == 1; assert _m1_findings[0].relative_path == 'shortcut.py'; assert _m1_findings[0].source.startswith('Account(user_id=uuid.uuid4()')
