tached_owner_guard.scan_paths([_m2_tmp / 'apps' / 'backend' / 'tests'], repo_root=_m2_tmp); _m2_names = {_m2_finding.source for _m2_finding in _m2_findings}; assert len(_m2_findings) == 2; assert any(('Literal var' in _m2_name for _m2_name in _m2_names)); assert any(('Appended' in _m2_name for _m2_name in _m2_names)); 'AC8.13.130'; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); 'AC8.13.130'; _m3_test_file = _m3_tmp / 'apps' / 'backend' / 'tests' / 'test_persist.py'; _m3_test_file.parent.mkdir(parents=True); _m3_test_file.write_text('\nfrom uuid import uuid4\n\nfrom src.models import Account\n\n\ndef test_merge(db):\n    db.merge(Account(user_id=uuid4(), name="Merged", type="ASSET", currency="SGD"))\n\n\ndef test_bulk(db):\n    db.bulk_save_objects([Account(user_id=uuid4(), name="Bulk", type="ASSET", currency="SGD")])\n'.lstrip(), encoding='utf-8'); _m3_findings = detached_owner_guard.scan_paths([_m3_tmp / 'apps' / 'backend' / 'tests'], repo_root=_m3_tmp); _m3_names = {_m3_finding.source for _m3_finding in _m3_findings}; assert len(_m3_findings) == 2; assert any(('Merged' in _m3_name for _m3_name in _m3_names)); assert any(('Bulk' in _m3_name for _m3_name in _m3_names)); 'AC8.13.128'; _m4_tmp = tmp_path / '_m4'; _m4_tmp.mkdir(exist_ok=True); 'AC8.13.128'; _m4_test_file = _m4_tmp / 'apps' / 'backend' / 'tests' / 'test_safe.py'; _m4_test_file.parent.mkdir(parents=True); _m4_test_file.write_text('\nfrom uuid import uuid4\n\nfrom src.models import Account\n\n\ndef test_safe(user):\n    owner_id = uuid4()\n    Account(user_id=user.id, name="Real user", type="ASSET", currency="SGD")\n    Account(user_id=owner_id, name="Assigned first", type="ASSET", currency="SGD")\n'.lstrip(), encoding='utf-8'); assert detached_owner_guard.scan_paths([_m4_test_file], repo_root=Path('/outside/root')) == []
def test_AC8_13_128_budget_fails_on_growth() -> None: 'AC-testing.schema.5 AC8.13.128'; finding = detached_owner_guard.DetachedOwnerFinding(relative_path='apps/backend/tests/accounting/test_shortcut.py', line=1, pattern='user_id=uuid4()', source='Account(user_id=uuid4())'); result = detached_owner_guard.evaluate_budget([finding], max_allowed=0); assert result.ok is False; assert result.count == 1; assert 'exceeds allowed budget 0' in result.message; 'AC8.13.128'; 'AC8.13.128'; _m5_findings = [detached_owner_guard.DetachedOwnerFinding(relative_path=f'apps/backend/tests/test_{_m5_index}.py', line=_m5_index + 1, pattern='user_id=uuid4()', source='Account(user_id=uuid4())') for _m5_index in range(3)]; _m5_output = detached_owner_guard._format_findings(_m5_findings, limit=2); assert 'apps/backend/tests/test_0.py:1: user_id=uuid4()' in _m5_output; assert 'apps/backend/tests/test_1.py:2: user_id=uuid4()' in _m5_output; assert '... 1 more' in _m5_output; assert 'test_2.py' not in _m5_output; 'AC8.13.128'; 'AC8.13.128'; _m6_findings = detached_owner_guard.scan_paths([ROOT / _m6_path for _m6_path in detached_owner_guard.DEFAULT_TEST_ROOTS], repo_root=ROOT); _m6_result = detached_owner_guard.evaluate_budget(_m6_findings); assert _m6_result.ok, _m6_result.message; 'AC8.13.128'; 'AC8.13.128'; _m7_workflow = (ROOT / '.github' / 'workflows' / 'ci.yml').read_text(encoding='utf-8'); _m7_lint_block = _m7_workflow.split('  lint:', 1)[1].split('  schema-migrations:', 1)[0]; _m7_local_lint = (ROOT / 'common' / 'runtime' / 'dev' / 'cli.py').read_text(encoding='utf-8'); assert 'tools/check_detached_owner_shortcuts.py' in _m7_lint_block; assert 'tools/check_detached_owner_shortcuts.py' in _m7_local_lint; 'AC8.13.128'; 'AC8.13.128'; from tools import check_detached_owner_shortcuts; assert check_detached_owner_shortcuts.main is detached_owner_guard.main
